          const fallbackStateId = states[0] ? String(states[0].id || states[0].state_id || states[0].code || states[0].state_code || '').trim() : '';
          const selectedState = states.find(s => String(s.id || s.state_id || s.code || s.state_code || '').trim() === selectedStateId);
          const selectedCountryId = String(selectedState && (selectedState.country_id || selectedState.countryId || selectedState.country) || countries[0] && (countries[0].id || countries[0].country_id || countries[0].code || '') || '').trim();
